/** A deep-enough clone of DEFAULT_CONFIG for tests to mutate freely without cross-test bleed. */
export function testConfig(overrides: Partial<GraspConfig> = {}): GraspConfig {
  return {
    ...structuredClone(DEFAULT_CONFIG),
    ...overrides,
